d. Promise.all et méthodes.code:
const promesse1 = Promise.resolve(3);
const promesse2 = new Promise(resolve => setTimeout(() => resolve('foo'), 1000));
const promesse3 = Promise.resolve(42);

// Promise.all - attend que toutes se terminent
Promise.all([promesse1, promesse2, promesse3])
  .then(valeurs => console.log(valeurs)); // [3, 'foo', 42]

// Promise.allSettled - attend toutes, même en cas d'erreur
Promise.allSettled([promesse1, Promise.reject('erreur'), promesse3])
  .then(resultats => console.log(resultats));

// Promise.race - première qui se termine
Promise.race([promesse1, promesse2])
  .then(valeur => console.log(valeur)); // 3

// Promise.any - première qui réussit
Promise.any([Promise.reject('err'), promesse2])
  .then(valeur => console.log(valeur)); // 'foo'

