// Format simple
function formaterDate(date) {
  const j = date.getDate().toString().padStart(2, '0');
  const m = (date.getMonth() + 1).toString().padStart(2, '0');
  const a = date.getFullYear();
  return `${j}/${m}/${a}`;
}

